use std::process::Command;
use std::os::unix::ffi::OsStrExt;
use std::ffi::OsStr;

fn run(bytes: &[u8]) -> String {
    let out = Command::new("/workspace/dataset/test4_executable")
        .arg(OsStr::from_bytes(bytes)).output().unwrap();
    String::from_utf8_lossy(&out.stdout).replace('\n',"")
}
fn pred(b: &[u8]) -> (u8,u8) {
    let hi = b.iter().any(|&c| c >= 0x80);
    (if hi {0} else {1}, if hi {1} else {0})
}
fn check(b: &[u8], bad: &mut usize) {
    let o = run(b);
    let ch: Vec<char> = o.chars().collect();
    if ch.len()!=4 { println!("WEIRD len {:?} for {:02x?}", o, b); *bad+=1; return; }
    let (ea, ei) = pred(b);
    let a = ch[2] as u8 - b'0';
    let i = ch[3] as u8 - b'0';
    if a!=ea || i!=ei {
        println!("COUNTEREXAMPLE bytes={:02x?} out={} expected ascii={} idn={}", b, o, ea, ei);
        *bad+=1;
    }
}
fn main(){
    let mode = std::env::args().nth(1).unwrap_or_default();
    let mut bad=0usize; let mut n=0usize;
    if mode=="pairs" {
        for x in 1u16..=255 { for y in 1u16..=255 {
            check(&[x as u8, y as u8], &mut bad); n+=1;
        }}
    } else if mode=="triples" {
        // all lead-byte-ish first bytes x, exhaustive 2nd/3rd from a stride
        let firsts: Vec<u8> = (0xc0u16..=0xffu16).map(|v| v as u8).collect();
        for &x in &firsts { for y in 1u16..=255 { for z in [1u8,0x2e,0x41,0x61,0x7f,0x80,0xbf,0xc0,0xed,0xf4,0xfe,0xff] {
            check(&[x,y as u8,z], &mut bad); n+=1;
        }}}
    } else {
        // random fuzz
        let mut s: u64 = 0x12345678;
        let mut r = || { s ^= s<<13; s^=s>>7; s^=s<<17; s };
        for _ in 0..40000 {
            let len = (r() % 40) as usize + 1;
            let mut v = Vec::with_capacity(len);
            for _ in 0..len {
                let pick = r()%10;
                let b = match pick {
                    0..=3 => (r()%0x7f) as u8 + 1,
                    4..=8 => 0x80 + (r()%0x80) as u8,
                    _ => *[b'.',b'-',b'a',b'Z',b'0',0x7f,0xc0,0x80,0xfe,0xff].get((r()%10) as usize).unwrap(),
                };
                v.push(if b==0 {1} else {b});
            }
            check(&v, &mut bad); n+=1;
        }
    }
    println!("mode={} tested={} mismatches={}", mode, n, bad);
}
